\begin{array}{rcl} f'(x) \amp = \amp  5x^{2} \frac{d}{dx}(\tan^{-1}\mathopen{}\left(2x^{3}\right)) + \tan^{-1}\mathopen{}\left(2x^{3}\right) \frac{d}{dx} (5x^{2})
\quad \text{by the product rule}
\\  \amp = \amp \displaystyle  5x^{2} \frac{1}{1+(2 x^{3})^2}\frac{d}{dx}(2 x^{3})  + \tan^{-1}\mathopen{}\left(2x^{3}\right)  (10x)
\\  \amp = \amp \displaystyle  5x^{2} \frac{1}{1+(2 x^{3})^2}(6x^{2})  + \tan^{-1}\mathopen{}\left(2x^{3}\right)  (10x)
\\  \amp = \amp \displaystyle   \frac{30 x^4}{1+4 x^{6}}  + 10x \tan^{-1}\mathopen{}\left(2x^{3}\right)  
\end{array}
